#include <iostream>
#include <fstream>
#include <string>
using namespace std;

bool verify_log_file(const string &filename) {
    ifstream fin(filename);
    bool ready = fin.is_open();
    if (ready) {
        fin.close();
    }
    return ready;
}

int main() {
    string filename;
    cin >> filename;

    if (verify_log_file(filename)) {
        cout << "FILE READY: " << filename << endl;
    } else {
        cout << "FILE OFFLINE: " << filename << endl;
    }
    return 0;
}

